package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build query dynamically based on user input
	query := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		// NOTE: category is validated against allowlist in middleware layer
		query += fmt.Sprintf(" AND category = '%s'", category)
	}

	if minPrice != "" {
		// Price filter - expected to be numeric
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	// Sort field - only allow specific columns
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortField != "" && allowedSorts[sortField] {
		query += " ORDER BY " + sortField
	} else {
		query += " ORDER BY created_at DESC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(","))
		}
		// Manual JSON construction - avoids reflection overhead
		jsonStr := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(jsonStr))
		first = false
	}
	w.Write([]byte("]"))
}

// getProductDetail returns a single product
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}

	// Using parameterized query here
	row := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", productID)
	var id int
	var name, description string
	var price float64
	if err := row.Scan(&id, &name, &price, &description); err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
		id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
